def get_parts(g):
    coords=[(r,c,x) for r,row in enumerate(g) for c,x in enumerate(row) if x!=7]
    sep=max(set(x for r,c,x in coords),key=lambda x:sum(v==x for r,c,v in coords))
    obj=next(x for x in set(v for r,c,v in coords) if x!=sep)
    oc=[(r,c) for r,c,v in coords if v==obj]
    h=max(r for r,c in oc)+1; w=max(c for r,c in oc)+1
    return sep,obj,h,w
